package com.citacloud.springboot.contacloud.app.views;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.services.*;import com.citacloud.springboot.contacloud.app.views.components.*;import com.vaadin.flow.component.button.Button;import com.vaadin.flow.component.checkbox.Checkbox;import com.vaadin.flow.component.confirmdialog.ConfirmDialog;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.grid.Grid;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.notification.Notification;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.data.value.ValueChangeMode;import java.math.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.function.Consumer;
final class SupplierPaymentApplicationDialog{
 private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd/MM/yyyy");private final SupplierPaymentService service;private final PagoProveedorDto payment;private final Consumer<PagoProveedorDto> afterApply;private final Map<UUID,BigDecimal>allocations=new LinkedHashMap<>();private final Map<UUID,FacturaAplicacionCreditoDto>known=new HashMap<>();private final Grid<FacturaAplicacionCreditoDto>grid=new Grid<>(FacturaAplicacionCreditoDto.class,false);private final TextField search=new TextField();private final Span totalValue=new Span(),remainingValue=new Span();private final AppActionButton apply;private final AppPagination[]pagination=new AppPagination[1];private Dialog dialog;
 SupplierPaymentApplicationDialog(SupplierPaymentService service,PagoProveedorDto payment,Consumer<PagoProveedorDto>afterApply){this.service=service;this.payment=payment;this.afterApply=afterApply;apply=new AppActionButton(ActionType.APPLY_CREDIT,ButtonSize.MAIN,"Aplicar pago",e->confirm());configure();}
 void open(){dialog=new Dialog();dialog.setHeaderTitle("APLICAR PAGO");dialog.setWidth("min(1180px,96vw)");dialog.setHeight("min(880px,94vh)");dialog.add(new AppDetailSection("INFORMACIÓN DEL PAGO").field("Proveedor",payment.proveedor()).field("Pago",payment.numero()).field("Moneda",payment.moneda()).field("Monto original",currency(payment.monto())).field("Aplicado",currency(payment.aplicado())).field("DISPONIBLE",currency(payment.disponible())));search.setPlaceholder("Buscar factura...");search.setClearButtonVisible(true);search.setValueChangeMode(ValueChangeMode.LAZY);search.addValueChangeListener(e->{if(e.isFromClient()){pagination[0].reset();load();}});Button automatic=new Button("Aplicar automáticamente",e->{allocations.clear();service.propose(payment.id()).forEach(x->allocations.put(x.facturaId(),x.monto()));refresh();});Button clear=new Button("Limpiar",e->{allocations.clear();refresh();});HorizontalLayout tools=new HorizontalLayout(search,automatic,clear);tools.setWidthFull();tools.expand(search);pagination[0]=new AppPagination(r->load(),5,5,10,25,50);VerticalLayout panel=new VerticalLayout(new H3("FACTURAS PENDIENTES"),tools,grid,pagination[0]);panel.setPadding(false);panel.setSizeFull();panel.expand(grid);dialog.add(panel);Div summary=new Div(metric("Disponible inicial",currency(payment.disponible())),metric("Total a aplicar",totalValue),metric("Restante",remainingValue));summary.addClassName("cc-invoice-totals");summary.getStyle().set("display","grid").set("grid-template-columns","repeat(3,minmax(150px,1fr))").set("gap","24px").set("flex","1");dialog.getFooter().getElement().getStyle().set("width","100%");dialog.getFooter().add(summary,apply,new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->dialog.close()));refreshSummary();load();dialog.open();}
 private void configure(){grid.setWidthFull();grid.setHeight("360px");grid.addComponentColumn(f->{Checkbox c=new Checkbox();c.setValue(amount(f.facturaId()).signum()>0);c.addValueChangeListener(e->{if(!e.isFromClient())return;if(e.getValue()){BigDecimal remaining=payment.disponible().subtract(total());BigDecimal proposed=f.saldo().min(remaining.max(BigDecimal.ZERO));if(proposed.signum()>0)allocations.put(f.facturaId(),proposed);}else allocations.remove(f.facturaId());refresh();});return c;}).setWidth("55px").setFlexGrow(0);grid.addColumn(FacturaAplicacionCreditoDto::numeroInterno).setHeader("Factura").setAutoWidth(true);grid.addColumn(FacturaAplicacionCreditoDto::numeroProveedor).setHeader("No. proveedor").setAutoWidth(true);grid.addColumn(f->DATE.format(f.fecha())).setHeader("Fecha").setAutoWidth(true);grid.addColumn(f->currency(f.saldo())).setHeader("Saldo").setAutoWidth(true);grid.addComponentColumn(f->{BigDecimalField x=new BigDecimalField();x.setWidth("130px");x.setValue(amount(f.facturaId()));x.addValueChangeListener(e->{if(!e.isFromClient())return;BigDecimal v=e.getValue()==null?BigDecimal.ZERO:e.getValue();if(v.signum()<=0)allocations.remove(f.facturaId());else allocations.put(f.facturaId(),v);refresh();});return x;}).setHeader("Aplicar").setWidth("150px").setFlexGrow(0);grid.setEmptyStateText("No hay facturas pendientes.");}
 private void load(){var r=pagination[0].currentRequest();var page=service.pendingInvoices(payment.proveedorId(),payment.monedaId(),search.getValue(),r.page(),r.size());page.forEach(x->known.put(x.facturaId(),x));grid.setItems(page.getContent());pagination[0].setTotal(page.getTotalElements());}private void refresh(){grid.getDataProvider().refreshAll();refreshSummary();}private void refreshSummary(){totalValue.setText(currency(total()));remainingValue.setText(currency(payment.disponible().subtract(total())));apply.setEnabled(valid());}private boolean valid(){if(total().signum()<=0||total().compareTo(payment.disponible())>0)return false;return allocations.entrySet().stream().allMatch(x->x.getValue()!=null&&x.getValue().signum()>0&&(!known.containsKey(x.getKey())||x.getValue().compareTo(known.get(x.getKey()).saldo())<=0));}
 private void confirm(){if(!valid())return;ConfirmDialog c=new ConfirmDialog("CONFIRMAR APLICACIÓN","¿Desea aplicar "+currency(total())+" del pago "+payment.numero()+"?","Confirmar",e->apply(),"Cancelar",e->{});c.open();}private void apply(){try{PagoProveedorDto result=service.apply(payment.id(),new AplicarPagoProveedorInput(allocations.entrySet().stream().map(x->new PagoProveedorInput.Aplicacion(x.getKey(),x.getValue())).toList(),payment.version()));dialog.close();afterApply.accept(result);Notification.show("Pago aplicado correctamente.");}catch(RuntimeException e){Notification.show(e instanceof ReglaNegocioException||e instanceof RecursoNoEncontradoException?e.getMessage():"No fue posible aplicar el pago. Actualiza los saldos e inténtalo nuevamente.");load();}}
 private BigDecimal total(){return allocations.values().stream().filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);}private BigDecimal amount(UUID id){return allocations.getOrDefault(id,BigDecimal.ZERO);}private String currency(BigDecimal v){String s="DOP".equalsIgnoreCase(payment.moneda())?"RD$":payment.moneda();return s+" "+String.format(Locale.US,"%,.2f",v==null?BigDecimal.ZERO:v);}private static Div metric(String label,String value){return metric(label,new Span(value));}private static Div metric(String label,Span value){Div d=new Div(new Span(label),value);d.getStyle().set("display","flex").set("flex-direction","column");value.getStyle().set("font-weight","700");return d;}
}
